// CommuLingo guided reading (format 'guided-reading'): each lesson shows a
// passage of the site's full translation first, then one question on it, with
// four choices (as in the Materialism and Empirio-criticism course). Korean
// passages are verbatim from the document engels-ludwig-feuerbach-1886
// (scripts/check-course-source-excerpts.js checks them and their anchors).
// Engels wrote the book in German, so the English passages are translated here
// from the German text the document carries. A passage may skip text with ' … '.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/engels-ludwig-feuerbach-1886';
const BOOK = 'engels-ludwig-feuerbach';
const FROM_GERMAN = ' (our translation from the German)';
const TITLE_KO = '『루트비히 포이어바흐와 독일 고전철학의 종말』';
const TITLE_EN = 'Ludwig Feuerbach and the End of Classical German Philosophy';

const LABELS = {
    preface: t('엥겔스, 1888년 단행본 서문', 'Engels, preface to the 1888 edition' + FROM_GERMAN),
    'part-1': t(`${TITLE_KO} I장`, `${TITLE_EN}, part I` + FROM_GERMAN),
    'part-2': t(`${TITLE_KO} II장`, `${TITLE_EN}, part II` + FROM_GERMAN),
    'part-3': t(`${TITLE_KO} III장`, `${TITLE_EN}, part III` + FROM_GERMAN),
    'part-4': t(`${TITLE_KO} IV장`, `${TITLE_EN}, part IV` + FROM_GERMAN),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `${BOOK}-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: 1,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-basic`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

